async function fetchSwimValues(bodyObj, type) {
console.log("fetchSwimValues called with type:", type, "bodyObj:", bodyObj);
let map = {
swimmer: "https://usaswimming.sisense.com/api/datasources/Public Person Search/jaql",
event: "https://usaswimming.sisense.com/api/datasources/USA Swimming Times Elasticube/jaql",
meet: "https://usaswimming.sisense.com/api/datasources/Meets/jaql",
};
let url = map[type || "swimmer"];
console.log("Making API call to:", url);
let response = await fetch(url, {
method: "POST",
headers: {
"Content-Type": "application/json",
Authorization:
"Bearer eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJ1c2VyIjoiNjY0YmE2NmE5M2ZiYTUwMDM4NWIyMWQwIiwiYXBpU2VjcmV0IjoiNDQ0YTE3NWQtM2I1OC03NDhhLTVlMGEtYTVhZDE2MmRmODJlIiwiYWxsb3dlZFRlbmFudHMiOlsiNjRhYzE5ZTEwZTkxNzgwMDFiYzM5YmVhIl0sInRlbmFudElkIjoiNjRhYzE5ZTEwZTkxNzgwMDFiYzM5YmVhIn0.izSIvaD2udKTs3QRngla1Aw23kZVyoq7Xh23AbPUw1M",
},
body: JSON.stringify(bodyObj),
});
if (!response.ok) {
console.log(
"API response not ok:",
response.status,
response.statusText,
);
return;
}
let data = await response.json();
console.log("API response data structure:", {
hasError: !!data.error,
hasValues: !!data.values,
hasHeaders: !!data.headers,
valuesLength: data.values?.length || 0,
headersLength: data.headers?.length || 0,
headers: data.headers
});
if (data.error || !data.values) {
console.log(
"API returned error or no values:",
data.error,
!!data.values,
);
return;
}
if (!data.headers) {
console.error("API response missing headers:", data);
return;
}
let idx = {};
for (let i = 0; i < data.headers.length; ++i) {
idx[data.headers[i]] = i;
}
data.values.idx = idx;
console.log("Created idx mapping:", idx);
return data.values;
}
class ClubDictinary {
#dict;
constructor() {
this.#dict = new Map();
}
static async #load(lsc) {
return await LocalCache.func(
"clubs/" + lsc,
async () => {
let bodyObj = {
metadata: [
{
title: "clubName",
dim: "[Persons.ClubName]",
datatype: "text",
},
{
dim: "[Persons.LscCode]",
datatype: "text",
filter: {
equals: lsc,
},
panel: "scope",
},
],
count: 5000,
};
let values = await fetchSwimValues(bodyObj);
if (!values) {
return;
}
console.log(`ClubDictionary.#load: First API call result for ${lsc}:`, {
hasValues: !!values,
isArray: Array.isArray(values),
length: values.length,
hasIdx: !!values.idx,
idxKeys: values.idx ? Object.keys(values.idx) : 'no idx'
});
if (!values.idx) {
console.error(`ClubDictionary.#load: Missing idx in first API response for ${lsc}`);
return;
}
let names = values.map((v) => v[values.idx.clubName]);
bodyObj = {
metadata: [
{
title: "club",
dim: "[OrgUnit.Level4Code]",
datatype: "text",
},
{
title: "clubName",
dim: "[OrgUnit.Level4Name]",
datatype: "text",
filter: {
members: names,
},
},
{
dim: "[OrgUnit.Level3Code]",
datatype: "text",
filter: {
equals: lsc,
},
panel: "scope",
},
],
count: names.length,
};
let clubCodes = await fetchSwimValues(bodyObj, "event");
console.log(`ClubDictionary.#load: Second API call result for ${lsc}:`, {
hasClubCodes: !!clubCodes,
isArray: Array.isArray(clubCodes),
length: clubCodes?.length || 0,
hasIdx: !!clubCodes?.idx,
idxKeys: clubCodes?.idx ? Object.keys(clubCodes.idx) : 'no idx'
});
return clubCodes;
},
window._1WeekInSec || (7 * 24 * 60 * 60),
);
}
async loadClubMap(lsc) {
console.log(`ClubDictionary.loadClubMap: Loading club map for lsc="${lsc}"`);
let map = this.#dict.get(lsc);
if (map) {
console.log(`ClubDictionary.loadClubMap: Using cached map for ${lsc}, size=${map.size}`);
return map;
}
console.log(`ClubDictionary.loadClubMap: Cache miss, loading fresh club data for ${lsc}`);
let cacheKey = "clubs/" + lsc;
console.log(`ClubDictionary.loadClubMap: Checking cache for key "${cacheKey}"`);
let cachedData = await LocalCache.get(cacheKey);
if (cachedData && (!cachedData.idx || !Array.isArray(cachedData))) {
console.log(`ClubDictionary.loadClubMap: Found corrupted cache data, clearing for ${lsc}`, cachedData);
localStorage.removeItem(cacheKey);
}
let data = await ClubDictinary.#load(lsc);
console.log(`ClubDictionary.loadClubMap: API call completed for ${lsc}`, {
hasData: !!data,
isArray: Array.isArray(data),
length: data?.length || 0,
hasIdx: !!(data?.idx),
dataType: typeof data
});
if (data && !data.idx && Array.isArray(data)) {
console.log(`ClubDictionary.loadClubMap: Data missing idx, clearing cache and reloading for ${lsc}`);
localStorage.removeItem(cacheKey);
data = await ClubDictinary.#load(lsc);
console.log(`ClubDictionary.loadClubMap: Reload completed for ${lsc}`, {
hasData: !!data,
hasIdx: !!(data?.idx)
});
}
if (data && data.idx) {
map = new Map();
let idx = data.idx;
console.log(`ClubDictionary.loadClubMap: Building club map from ${data.length} entries`);
for (let row of data) {
if (row[idx.club]) {
map.set(row[idx.club], row[idx.clubName]);
}
}
console.log(`ClubDictionary.loadClubMap: Club map built for ${lsc} with ${map.size} entries`);
if (map.size > 0) {
console.log(`ClubDictionary.loadClubMap: First few clubs in ${lsc}:`,
Array.from(map.entries()).slice(0, 5).map(([code, name]) => `${code}="${name}"`));
}
this.#dict.set(lsc, map);
} else {
console.warn(`ClubDictionary.loadClubMap: Failed to load club data for ${lsc}`);
}
return map;
}
async loadClubName(lsc, club) {
console.log(`ClubDictionary.loadClubName: Looking up club="${club}" in lsc="${lsc}"`);
let map = await this.loadClubMap(lsc);
console.log(`ClubDictionary.loadClubName: loadClubMap returned:`, {
hasMap: !!map,
mapType: typeof map,
mapSize: map?.size || 0
});
if (!map) {
console.warn(`ClubDictionary.loadClubName: No club map available for lsc="${lsc}"`);
return;
}
let clubName = map.get(club);
console.log(`ClubDictionary.loadClubName: Club lookup result:`, {
searchedFor: club,
found: clubName,
hasResult: !!clubName
});
if (!clubName && map.size > 0) {
console.log(`ClubDictionary.loadClubName: Club "${club}" not found. Available clubs in ${lsc}:`,
Array.from(map.entries()).slice(0, 10).map(([code, name]) => `${code}="${name}"`));
}
return clubName;
}
async loadClubCode(lsc, clubName) {
let map = await this.loadClubMap(lsc);
if (!map) {
return;
}
for (let [code, name] of map) {
if (name == clubName) {
return code;
}
}
}
}
class MeetDictionary {
#dict;
constructor() {
this.#dict = new Map();
this.#dict.idx = { date: 0, name: 1 };
}
static async #load(meets) {
let bodyObj = {
metadata: [
{
title: "meet",
dim: "[UsasSwimTime.MeetKey]",
datatype: "numeric",
filter: {
members: [...meets],
},
},
{
title: "date",
dim: "[SeasonCalendar.CalendarDate (Calendar)]",
datatype: "datetime",
level: "days",
sort: "asc",
},
{
title: "meetName",
dim: "[Meet.MeetName]",
datatype: "text",
},
],
count: meets.size * 5,
};
let data = await fetchSwimValues(bodyObj, "event");
if (!data) {
return;
}
let idx = data.idx;
let result = [];
for (let row of data) {
let meet = row[idx.meet];
if (meets.has(meet)) {
meets.delete(meet);
row[idx.date] = row[idx.date].substring(0, 10);
result.push(row);
}
}
result.idx = idx;
return result;
}
static async #loadCached(meets) {
let result = [];
for (let meet of meets) {
let key = "meet/" + meet;
let data = await LocalCache.get(key, _10YearsInSec || (10 * 365 * 24 * 60 * 60));
if (data) {
let [date, meetName] = data;
result.push([meet, date, meetName]);
meets.delete(meet);
}
}
if (meets.size == 0) {
return result;
}
let data = await MeetDictionary.#load(meets);
if (data) {
let idx = data.idx;
for (let row of data) {
let meet = row[idx.meet];
let date = row[idx.date];
let meetName = row[idx.meetName];
result.push([meet, date, meetName]);
LocalCache.set("meet/" + meet, [date, meetName]);
}
}
return result;
}
async loadMeets(meets) {
let meetsToLoad = new Set();
for (let meet of meets) {
if (!this.#dict.has(meet)) {
meetsToLoad.add(meet);
}
}
let data = await MeetDictionary.#loadCached(meetsToLoad);
if (data) {
for (let [meet, date, meetName] of data) {
this.#dict.set(meet, [date, meetName]);
}
}
return this.#dict;
}
}
class BirthdayDictionary {
#dict;
constructor() {
this.#dict = new Map();
}
async load(pkey) {
let data = this.#dict.get(pkey);
if (data) {
return data;
}
data = await LocalCache.get("bday/" + pkey, _10YearsInSec);
if (data) {
this.#dict.set(pkey, data);
return data;
}
}
calculate(pkey, events, meetDict, age) {
if (!events || !events.idx) {
console.log(
"BirthdayDictionary.calculate: events missing idx property",
);
return null;
}
let now = new Date();
let nowYear = now.getUTCFullYear();
let nowMonth = now.getUTCMonth();
let nowDate = now.getUTCDate();
let left = new Date(Date.UTC(1900, 0, 1));
let right = new Date(Date.UTC(nowYear, nowMonth, nowDate));
if (age) {
right.setUTCFullYear(nowYear - age, nowMonth, nowDate);
left.setUTCFullYear(nowYear - age - 1, nowMonth, nowDate + 1);
}
for (let row of events) {
let meet = row[events.idx.meet];
let meetDate = meetDict.get(meet)[meetDict.idx.date];
let meetAge = row[events.idx.age];
let d = new Date(meetDate);
d.setUTCFullYear(
d.getUTCFullYear() - meetAge,
d.getUTCMonth(),
d.getUTCDate(),
);
right = min(d, right);
d = new Date(meetDate);
d.setUTCFullYear(
d.getUTCFullYear() - meetAge - 1,
d.getUTCMonth(),
d.getUTCDate() + 1,
);
left = max(d, left);
}
left = left.toJSON().substring(0, 10);
right = right.toJSON().substring(0, 10);
if (left > right) {
console.error(
"Invalid birthday:" + pkey + "  [" + left + " - " + right + "]",
);
right = left;
}
let range = [left, right];
LocalCache.set("bday/" + pkey, range);
this.#dict.set(pkey, range);
return range;
}
static format(range) {
if (!range) {
return "";
}
let html = [];
let [left, right] = range;
left = left.replace(/-0/g, "-").replace(/-/g, "/");
right = right.replace(/-0/g, "-").replace(/-/g, "/");
html.push(left);
if (left != right) {
html.push(" - ");
if (left.substring(0, 4) == right.substring(0, 4)) {
right = right.substring(5);
}
html.push(right);
}
return html.join("");
}
}
let _clubDictinary = new ClubDictinary();
let _meetDictinary = new MeetDictionary();
let _birthdayDictionary = new BirthdayDictionary();
window._clubDictinary = _clubDictinary;
window._meetDictinary = _meetDictinary;
window._birthdayDictionary = _birthdayDictionary;
window.BirthdayDictionary = BirthdayDictionary;
window.fetchSwimValues = fetchSwimValues;